"""Create immutable engineering inputs; no parameter tuning or target labels."""
import argparse,csv,json
from pathlib import Path
from .common import ROOT,MODALITIES,canonical,read,sha,atomic_json,p0_context,require
def create_policy(inputs):
 require(inputs["scores"]["active_deferred"]["status"]=="not_frozen","Unexpected P0 policy; revise protocol explicitly")
 return dict(schema_version="cue_policy_v1",cue_id_order=inputs["cue_id_order"],thresholds=inputs["scores"]["engineering_thresholds"],threshold_status="uncalibrated_0.5",calibration=dict(method="identity",status="uncalibrated",version="p0_uncalibrated_identity_v1",artifact=None),human_active_decisions_available=False,profiles=dict(engineering=dict(status="engineering_all_slots_pending_human_active_decision",active_mask=[True]*42,deferred_mask=[False]*42,rationale="Expose existing 42 supervised output slots for engineering checks only; no Cue has a new human reliability decision"),deployment=dict(status="blocked_pending_human_active_deferred_freeze",active_mask=[False]*42,deferred_mask=[True]*42,rationale="Fail closed until Cue protocol human audit and deployment activation decisions are frozen")),constraints=["No AMG threshold re-estimation","No score-based inference of unobservability or uncertainty","No special rules for tearing or frequent pauses"])
def create_query_config(inputs,dimensions):
 return dict(schema_version="amg_query_config_v1",purpose="engineering_contract_tests",graph_release_id=inputs["graph"]["release_id"],frozen_build_constraints=dict(inputs["graph"]["frozen_build_constraints"]),query_parameters=dict(query_min_support_groups=20,query_path_min_joint_support_groups=5,dimension_min_evidence={d:0.0 for d in dimensions},minimum_coverage=0.0,emotion_top_k=5,path_top_k=10,direct_two_hop_lambda=0.5,branch="full"),notes="Executable smoke-test profile only. K=5/lambda=0.5 reuse the old structural proxy convention; zero evidence/coverage cutoffs and path K=10 are engineering settings, not P4-selected values. Query filters never resurrect excluded graph edges/paths.")
def create_schemas(inputs):
 nullable_score={"anyOf":[{"type":"number","minimum":0,"maximum":1},{"type":"null"}]}
 vec=lambda items:dict(type="array",minItems=42,maxItems=42,items=items)
 boolvec=vec({"type":"boolean"});numvec=vec({"type":"number","minimum":0,"maximum":1})
 string={"type":"string"};obj={"type":"object"};number={"type":"number"};boolean={"type":"boolean"}
 input_schema={"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"amg_current_sample_v1","type":"object","additionalProperties":False,"required":["sample_id"],"properties":dict(sample_id=dict(type="string",minLength=1),text=dict(type="object",additionalProperties=False,properties={l:{"type":["string","null"]} for l in ["chinese","english"]}),audio_path={"anyOf":[{"type":"string","pattern":"^/"},{"type":"null"}]},video_path={"anyOf":[{"type":"string","pattern":"^/"},{"type":"null"}]})}
 properties=dict(schema_version={"const":"cue_query_42_v1"},sample_id=string,cue_id_order={"const":inputs["cue_id_order"]},scores=vec(nullable_score),modality_present={"type":"object","required":list(MODALITIES),"additionalProperties":False,"properties":{m:boolean for m in MODALITIES}},availability_mask=boolvec,active_mask=boolvec,deferred_mask=boolvec,requested_mask=boolvec,query_allowed_mask=boolvec,selected_mask=boolvec,query_weights=numvec,cue_states=vec({"enum":["modality_unavailable","deferred","not_requested","selected","below_threshold"]}),thresholds=numvec,threshold_status={"const":"uncalibrated_0.5"},calibration=obj,policy_profile={"enum":["engineering","deployment"]},policy_status=string,policy_id=string,selected_cues={"type":"array"},model_versions=obj,cue_release_id=string,graph_release_id=string,diagnostics=obj,input_fingerprints=obj,fallback={"type":"object","required":["required","reason","target"],"properties":dict(required=boolean,reason={"type":["string","null"]},target={"const":"original_affectgpt"})},semantics=string,query_input_id=string,runtime_release_id=string)
 cue_schema={"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"cue_query_42_v1","type":"object","additionalProperties":False,"properties":properties,"required":list(properties)}
 candidate={"type":"object","required":["emotion_id","association_score","direct_available","two_hop_available","query_coverage"],"properties":dict(emotion_id=string,association_score={"type":"number","minimum":0,"maximum":1},direct_available=boolean,two_hop_available=boolean,query_coverage={"type":"number","minimum":0,"maximum":1})}
 path={"type":"object","required":["path_id","path_type","edge_ids","edge_weights","edge_support_count_groups","joint_support_groups","joint_support_ratio","gates"],"properties":dict(path_id=string,path_type={"enum":["direct","two_hop"]},edge_ids={"type":"array","minItems":1,"maxItems":2,"items":string},edge_weights={"type":"array","minItems":1,"maxItems":2,"items":{"type":"number","exclusiveMinimum":0,"maximum":1}},edge_support_count_groups={"type":"array","items":{"type":"integer","minimum":20}})}
 query_schema={"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"amg_query_result_v1","type":"object","required":["schema_version","sample_id","runtime_release_id","graph_release_id","query_input_id","query_config_id","query_config","score_semantics","query_cues","query_weight_sum","appraisal_dimensions","emotion_candidates","explanation_paths","rejected_paths","coverage","fallback","input_snapshot","query_result_id"],"properties":dict(schema_version={"const":"amg_query_result_v1"},emotion_candidates={"type":"array","items":candidate},explanation_paths={"type":"array","items":path},input_snapshot=cue_schema,query_result_id={"type":"string","pattern":"^[0-9a-f]{64}$"})}
 integer={"type":"integer","minimum":0}
 params={"type":"object","additionalProperties":False,"required":["query_min_support_groups","query_path_min_joint_support_groups","dimension_min_evidence","minimum_coverage","emotion_top_k","path_top_k","direct_two_hop_lambda","branch"],"properties":dict(query_min_support_groups=integer,query_path_min_joint_support_groups=integer,dimension_min_evidence=dict(type="object",additionalProperties={"type":"number","minimum":0}),minimum_coverage={"type":"number","minimum":0,"maximum":1},emotion_top_k={"type":"integer","minimum":1,"maximum":1000},path_top_k={"type":"integer","minimum":1,"maximum":1000},direct_two_hop_lambda={"type":"number","minimum":0,"maximum":1},branch={"enum":["full","direct","appraisal"]})}
 config_schema={"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"amg_query_config_v1","type":"object","additionalProperties":False,"required":["schema_version","purpose","graph_release_id","frozen_build_constraints","query_parameters","notes"],"properties":dict(schema_version={"const":"amg_query_config_v1"},purpose={"enum":["engineering_contract_tests","source_validation_candidate","source_validation_frozen"]},graph_release_id=string,frozen_build_constraints={"const":inputs["graph"]["frozen_build_constraints"]},query_parameters=params,notes=string)}
 return {"current_sample.schema.json":input_schema,"cue_query_42.schema.json":cue_schema,"graph_query.schema.json":query_schema,"query_config.schema.json":config_schema}
def main():
 p=argparse.ArgumentParser();p.add_argument("--release",required=True);args=p.parse_args()
 directory=Path(args.release).resolve();pointer,lock,inputs=p0_context()
 require((directory/"weight_exports.json").is_file(),"Complete the safe exports before building the release")
 require(read(directory/"weight_exports.json")["p0_lock_id"]==lock["lock_id"],"Export/P0 version mismatch")
 policy=create_policy(inputs)
 graph=read(inputs["graph"]["graph_file"])
 dims=[n["id"] for n in graph["nodes"] if n["node_type"]=="AppraisalDimension"]
 atomic_json(directory/"cue_policy.json",policy)
 atomic_json(directory/"query_config.engineering.json",create_query_config(inputs,dims))
 for name,value in create_schemas(inputs).items():atomic_json(directory/"schemas"/name,value)
 files={}
 for p in sorted(directory.rglob("*.json")):
  if p.name in {"release_manifest.json","export_process.json"} or "validation" in p.parts:continue
  files[str(p.relative_to(directory))]=sha(p)
 code={str(p.relative_to(ROOT)):sha(p) for p in sorted((ROOT/"amg_runtime").rglob("*.py")) if "releases" not in p.relative_to(ROOT/"amg_runtime").parts}
 manifest=dict(schema_version="amg_runtime_release_v1",p0_lock_id=lock["lock_id"],cue_release_id=inputs["cue_release"]["release_id"],graph_release_id=inputs["graph"]["release_id"],files=files,source_code_sha256=code,selected_checkpoints={m:inputs["checkpoints"][m]["sha256"] for m in MODALITIES},engineering_profile_frozen=True,query_parameters_selected_by_P4=False,human_deployment_policy_frozen=False,final_target_evaluation_allowed=False,scope="P2/P3 engineering implementation; no model training, Teacher calls, graph rebuild or target labels")
 manifest["release_id"]=canonical(manifest);atomic_json(directory/"release_manifest.json",manifest)
 print(json.dumps(dict(release_id=manifest["release_id"],files=len(files),code_files=len(code))))
if __name__=="__main__":main()
